const input = $input.first().json.body ?? $input.first().json;
const callerNumber = String(input.callerNumber ?? '').trim();
const smsSender = String(input.smsSender ?? '').trim();
const businessName = String(input.businessName ?? 'ons team').trim();
const summary = String(input.summary ?? '').trim();
if (!/^\+[1-9]\d{7,14}$/.test(callerNumber)) {
  throw new Error('Ongeldig telefoonnummer: gebruik het internationale E.164-formaat.');
}
if (!/^\+[1-9]\d{7,14}$/.test(smsSender)) {
  throw new Error('Stel N8N_SMS_FROM_NUMBER in op een geldig Twilio-nummer in E.164-formaat.');
}
if (!summary) {
  throw new Error('Geen gesprekssamenvatting ontvangen; sms niet verstuurd.');
}
const message = `Bedankt voor uw telefoontje naar ${businessName}. Samenvatting: ${summary}`;
return [{ json: { callerNumber, smsSender, businessName, summary, message: message.slice(0, 1500) } }];
